import {ORDER,SCAN_ORDER,INFO,SOLVED,blankFaces,fromString,toString,rotateFace,validate,explain,calibrate} from './engine.mjs';
import {CubeView} from './cube-view.mjs';
import {Scanner} from './camera.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const icon=(name,size=20)=>{const paths={camera:'M14 4l1.5 3H20a2 2 0 012 2v10a2 2 0 01-2 2H4a2 2 0 01-2-2V9a2 2 0 012-2h4.5L10 4z M16 13a4 4 0 11-8 0 4 4 0 018 0',upload:'M12 16V3m-5 5l5-5 5 5M4 16v4a1 1 0 001 1h14a1 1 0 001-1v-4',check:'M5 12l4 4L19 6',play:'M8 4l13 8-13 8z',pause:'M8 5v14M16 5v14',rotate:'M3 10a9 9 0 119 11M3 4v6h6',hand:'M8 13V5a2 2 0 014 0v6-7a2 2 0 014 0v8-5a2 2 0 014 0v9c0 4-3 6-7 6-3 0-5-2-7-5l-3-4a2 2 0 013-2l2 2',book:'M12 5C8 2 4 3 2 4v15c4-2 7-1 10 1 3-2 6-3 10-1V4c-4-2-7-1-10 1zm0 0v15',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6',close:'M6 6l12 12M18 6L6 18',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z M15 12a3 3 0 11-6 0 3 3 0 016 0'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;};
let mode='scan',inputMode='camera',face='F',faces=blankFaces(),done=new Set(),samples={},uncertain={},paint='F',scanner=null,view=null,worker=null,solveGeneration=0,busy=false,animating=false,playing=false,moveIndex=0,moves=[],states=[],scanError='',demo=false,lesson=0;
const lessons=[{title:'Meet the three kinds of pieces',label:'01 · THE CUBE',body:'Centers have one color and stay in place relative to each other. They tell you what color each face will be when solved. Edges have two colors. Corners have three.',tip:'Find the green center. That is your front face—even if every other sticker around it is a different color.',face:'F'},{title:'Choose a home position',label:'02 · HOW TO HOLD IT',body:'Hold the white center on top and the green center facing you. The red center is on your right. Keep this home position throughout the guided solve.',tip:'Turning a face and rotating the entire cube are different actions. During a solution, turn only the face named in the move.',face:null},{title:'Read a move like a sentence',label:'03 · THE SIX LETTERS',body:'U is top, D is bottom, F is front, B is back, R is right, and L is left. A letter alone means a clockwise quarter-turn when looking straight at that face.',tip:'R means right clockwise. R′ means right counterclockwise. R2 means turn the right face halfway around.',face:'R'},{title:'Build your own solving method',label:'04 · THE BIGGER PICTURE',body:'A common beginner method builds a white cross, finishes the white layer, solves the middle edges, then works through the yellow cross, yellow face, and last-layer pieces.',tip:'This app’s guided solve uses a computed sequence for your exact scramble. It teaches you to follow turns, but it does not follow those layer-by-layer stages.',face:null}];
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function stopCamera(){scanner?.stop();scanner=null;}
function setMode(next){if(animating)return;playing=false;playGeneration++;if(busy){worker?.terminate();solveGeneration++;busy=false;}stopCamera();mode=next==='solve'&&!states.length?'review':next;render();}
function render(){
 document.body.dataset.mode=mode;
 $('#app').innerHTML=`<header><a class="brand" href="./" aria-label="Cube Coach home"><span class="brand-icon">▦</span> cube<span>coach</span></a><nav aria-label="Main"><button id="nav-solve" class="${mode!=='learn'?'active':''}">Solve my cube</button><button id="nav-learn" class="${mode==='learn'?'active':''}">Learn the basics</button></nav><span class="header-tag">3 × 3 CUBE</span></header><main><div class="intro"><div><div class="eyebrow">A LITTLE GUIDANCE. EVERY TURN.</div><h1>${mode==='learn'?'Make every move make sense.':mode==='solve'?'You’ve got this. One turn at a time.':'Let’s untangle your cube.'}</h1><p>${mode==='learn'?'Get to know your cube before your first solve.':mode==='solve'?'Keep your cube in the home position. We’ll take it from here.':'Scan six sides. Find your rhythm. Solve it together.'}</p></div><button id="demo" class="secondary">${icon('spark',17)} Try a demo</button></div><div class="steps" aria-label="Solving progress"><button data-step="scan" class="${mode==='scan'?'active':''}"><span>01</span> Add your cube ${done.size===6&&!demo?icon('check',14):''}</button><button data-step="review" class="${mode==='review'?'active':''}" ${!done.size?'disabled':''}><span>02</span> Check the colors</button><button data-step="solve" class="${mode==='solve'?'active':''}" ${!moves.length&&!states.length?'disabled':''}><span>03</span> Solve together</button></div><div class="workspace"><section class="panel" id="panel-content"></section><section class="cube-stage"><div class="stage-top"><span class="eyebrow">${mode==='solve'?'FOLLOW ALONG':'YOUR CUBE, IN 3D'}</span><span class="pill" id="cube-badge">${demo?'DEMO CUBE':done.size?'LIVE PREVIEW':'SCAN PREVIEW'}</span></div><div id="cube-canvas"></div><div class="cube-orientation"><span><i style="background:${INFO.U.hex}"></i> White on top</span><span><i style="background:${INFO.F.hex}"></i> Green in front</span></div><div class="stage-actions"><span>Drag the cube to look around</span><button id="reset-view">${icon('rotate',14)} Reset view</button></div><div class="stage-tip">${icon('hand',22)}<p id="stage-tip-text">${mode==='solve'?'Keep your real cube in the same position. Turn only the face shown in each instruction.':'Rotate the whole cube between scans. Don’t twist any of its layers.'}</p></div></section></div><div class="bottom-note"><span>${icon('shield',16)} Camera frames stay in your browser.</span><span>Made for standard 3×3 cubes <span class="dot-divider">·</span> Take your time. You’re learning.</span></div></main>`;
 $('#nav-solve').onclick=()=>setMode(states.length?'solve':done.size===6?'review':'scan');$('#nav-learn').onclick=()=>setMode('learn');$('#demo').onclick=loadDemo;
 $$('[data-step]').forEach(b=>b.onclick=()=>b.dataset.step==='scan'?scanCube():setMode(b.dataset.step));
 try{if(view){view.observer.disconnect();view.geometry.dispose();view.stickerGeometry.dispose();view.dark.dispose();Object.values(view.materials).forEach(m=>m.dispose());view.renderer.dispose();}view=new CubeView($('#cube-canvas'));view.setState(mode==='solve'&&states.length?fromString(states[moveIndex]):faces);}catch(e){$('#cube-canvas').innerHTML='<div class="view-fallback"><p>3D is unavailable in this browser.</p><p>You can still follow the written moves and color grids.</p></div>';view=null;}
 $('#reset-view').onclick=()=>view?.reset();
 if(mode==='scan')renderScan();else if(mode==='review')renderReview();else if(mode==='solve')renderSolve();else renderLearn();
}
function faceRail(){return `<div class="face-rail">${SCAN_ORDER.map(f=>`<button data-face="${f}" class="${face===f?'selected':''} ${done.has(f)?'complete':''}" aria-label="${INFO[f].name} face, ${done.has(f)?'captured':'not captured'}"><span class="mini-face">${faces[f].map(c=>`<i style="background:${INFO[c]?.hex||'#dee6df'}"></i>`).join('')}</span><span>${INFO[f].name}</span>${done.has(f)?'<b>✓</b>':''}</button>`).join('')}</div>`;}
function bindRail(){ $$('[data-face]').forEach(b=>b.onclick=()=>{stopCamera();face=b.dataset.face;renderScan();view?.setState(faces);}); }
function renderScan(){
 const p=$('#panel-content');p.innerHTML=`<div class="panel-heading"><div><div class="eyebrow">YOUR STARTING POINT</div><h2>Show me your cube.</h2></div><span class="counter">${done.size}<small>/ 6 faces</small></span></div><p class="panel-description">One face at a time. You can fix any color before solving.</p><div class="input-tabs" aria-label="Cube entry method">${[['camera','camera','Live camera'],['photo','upload','Upload'],['manual','hand','By hand']].map(([key,ic,text])=>`<button data-input="${key}" class="${inputMode===key?'active':''}" aria-pressed="${inputMode===key}">${icon(ic,16)}${text}</button>`).join('')}</div><div id="face-rail-wrap">${faceRail()}</div><div class="face-instruction"><span class="face-dot" style="background:${INFO[face].hex}"></span><div><b>${INFO[face].name} face <span>· ${INFO[face].color.toLowerCase()} center</span></b><p>${INFO[face].hint}</p></div></div><div id="scan-area"></div><div id="scan-error" class="error-message" role="alert" ${!scanError?'hidden':''}></div><div class="scan-bottom"><span id="scan-caption">${done.size?`${done.size} face${done.size>1?'s':''} ready`:'Start with any face above'}</span><button id="review" class="text-button" ${!done.size?'disabled':''}>Check colors ${icon('check',15)}</button></div>`;
 $('#scan-error').textContent=scanError;bindRail();$$('[data-input]').forEach(b=>b.onclick=()=>{stopCamera();inputMode=b.dataset.input;scanError='';renderScan();});$('#review').onclick=()=>{finishCalibration();setMode('review');};
 if(inputMode==='manual'){renderManual();return;}
 $('#scan-area').innerHTML=`<div class="scan-welcome"><div class="camera-icon">${icon(inputMode==='camera'?'camera':'upload',30)}</div><h3>${inputMode==='camera'?'Ready when you are.':'A clear view of one face.'}</h3><p>${inputMode==='camera'?'Fill the guide with one face, one dot per sticker.<br>Hold still for about 2 seconds.':'Add a photo, then drag and zoom<br>to line up the nine stickers.'}</p><button id="start-scan" class="primary">${icon(inputMode==='camera'?'camera':'upload',18)} ${inputMode==='camera'?'Start camera':'Choose a photo'}</button><span class="welcome-note">${inputMode==='camera'?'Phone camera or webcam · Bright, even light':'JPEG, PNG, WebP · Up to 25 MB'}</span></div><input id="photo-input" type="file" accept="image/*" hidden>`;
 $('#start-scan').onclick=inputMode==='camera'?startCamera:()=>$('#photo-input').click();$('#photo-input').onchange=e=>{if(e.target.files[0])openPhoto(e.target.files[0]);};
}
function showScanError(message){scanError=message;const box=$('#scan-error');if(box){box.hidden=!message;box.textContent=message;}}
function errorScan(message){showScanError(message);const status=$('#scan-status');if(status)status.textContent='Camera unavailable';const b=$('#capture-now');if(b)b.disabled=true;const restart=$('#restart-camera');if(restart)restart.hidden=false;}
function scannerSurface(photo=false){$('#scan-area').innerHTML=`<div class="capture-wrap"><canvas id="scan-canvas" aria-label="${photo?'Photo':'Live camera'} preview with a nine-sticker alignment guide"></canvas><video id="camera-video" autoplay muted playsinline class="source-video"></video><div class="scan-guide"><div class="guide-grid">${Array.from({length:9},(_,i)=>`<span id="guide-cell-${i}"><i></i></span>`).join('')}</div><span class="guide-top">${INFO[face].edge} face along this edge</span></div><div class="live-label">${photo?'ALIGN YOUR PHOTO':'LIVE CAMERA'}</div></div><div class="capture-status"><span id="scan-status" role="status">${photo?'Drag to align the stickers':'Opening camera…'}</span><span id="hold-time"></span></div><div class="hold-track"><div id="hold-progress"></div></div>${photo?'<div class="photo-controls"><label>Zoom <input id="photo-zoom" type="range" min="0.4" max="3" step="0.02" value="1"></label><button id="reset-photo" class="text-button">Reset framing</button><button id="rotate-photo" class="text-button">Rotate photo</button></div>':'<label class="auto-label"><input id="auto-capture" type="checkbox" checked> Capture automatically when steady</label>'}<div class="capture-actions"><button class="secondary" id="cancel-scan">${photo?'Choose another':'Stop camera'}</button><button class="primary" id="capture-now" disabled>${photo?'Use this face':'Capture now'}</button><button class="secondary" id="restart-camera" hidden>Retry camera</button></div>`;
 scanner=new Scanner({canvas:$('#scan-canvas'),video:$('#camera-video'),onReading:r=>{if(!$('#scan-status'))return;$('#scan-status').textContent=photo?(r.centerOK?'Drag and zoom until each dot sits on one sticker':`Put the ${INFO[face].color.toLowerCase()} center on the middle dot, or pick the matching face above`):r.message;$('#hold-time').textContent=!photo&&r.progress>0?`${Math.round(r.progress*100)}%`:'';$('#hold-progress').style.width=`${photo?0:r.progress*100}%`;r.colors.forEach((c,i)=>{let dot=$(`#guide-cell-${i} i`);dot.style.background=INFO[c]?.hex||'#fff';});$('#capture-now').disabled=r.colors.includes('?')||!r.centerOK;},onCapture:saveCapture,onError:errorScan});scanner.face=face;
 $('#cancel-scan').onclick=()=>{stopCamera();renderScan();};$('#capture-now').onclick=()=>scanner?.capture();$('#restart-camera').onclick=startCamera;
 if(photo){$('#reset-photo').onclick=()=>{scanner.dx=0;scanner.dy=0;scanner.scale=1;scanner.rotation=0;scanner.drag=null;$('#photo-zoom').value='1';scanner.drawPhoto();};$('#photo-zoom').oninput=e=>{scanner.scale=+e.target.value;scanner.drawPhoto();};$('#rotate-photo').onclick=()=>{scanner.rotation++;scanner.drawPhoto();};}else $('#auto-capture').onchange=e=>{scanner.auto=e.target.checked;scanner.stableAt=0;};
}
function startCamera(){stopCamera();scanError='';$('#scan-error').hidden=true;scannerSurface();scanner.start();}
async function openPhoto(file){stopCamera();scanError='';scannerSurface(true);try{await scanner.photo(file);}catch(e){errorScan(e.message);}}
function saveCapture(data){if(data.colors[4]!==face){showScanError(`The center should be ${INFO[face].color.toLowerCase()}. Select the matching face or try again.`);return;}showScanError('');faces[face]=data.colors;faces[face][4]=face;samples[face]=data;done.add(face);uncertain[face]=data.confidence.map((c,i)=>c<.55||data.uniform?.[i]===false?i:-1).filter(i=>i>=0&&i!==4);demo=false;states=[];moves=[];moveIndex=0;notify(`${INFO[face].name} face captured. ${done.size} of 6.`);view?.setState(faces);$('#cube-badge').textContent='LIVE PREVIEW';if(done.size===6){finishCalibration();setMode('review');return;}face=SCAN_ORDER.find(f=>!done.has(f));if(scanner?.active){scanner.setFace(face);$('#face-rail-wrap').innerHTML=faceRail();bindRail();$('.face-instruction').innerHTML=`<span class="face-dot" style="background:${INFO[face].hex}"></span><div><b>${INFO[face].name} face <span>· ${INFO[face].color.toLowerCase()} center</span></b><p>${INFO[face].hint}</p></div>`;$('.guide-top').textContent=INFO[face].edge+' face along this edge';$('.counter').innerHTML=`${done.size}<small>/ 6 faces</small>`;$('#scan-caption').textContent=`${done.size} face${done.size>1?'s':''} ready`;$('#review').disabled=false;$('[data-step=review]').disabled=false;$('[data-step=solve]').disabled=true;}else{stopCamera();renderScan();}}
function finishCalibration(){const c=calibrate(samples);if(c){faces=c.faces;uncertain=c.uncertain;view?.setState(faces);}}
function palette(){return `<div class="palette" aria-label="Sticker paint color">${ORDER.map(f=>`<button class="${paint===f?'selected':''}" data-paint="${f}" aria-label="Paint ${INFO[f].color.toLowerCase()}" aria-pressed="${paint===f}"><i style="background:${INFO[f].hex}">${paint===f?'✓':''}</i><span>${INFO[f].color}</span></button>`).join('')}</div>`;}
function faceGrid(f,large=false){return `<div class="sticker-grid ${large?'large':''}">${faces[f].map((c,i)=>`<button data-sticker="${f}:${i}" style="--sticker:${INFO[c]?.hex||'#e4eae3'}" class="${(uncertain[f]||[]).includes(i)?'uncertain':''}" aria-label="${INFO[f].name}, row ${Math.floor(i/3)+1}, column ${i%3+1}, ${INFO[c]?.color||'not filled'}${i===4?', fixed center':''}" ${i===4?'disabled':''}>${i===4?f:c==='?'?'+':''}</button>`).join('')}</div>`;}
function bindPaint(){ $$('[data-paint]').forEach(b=>b.onclick=()=>{paint=b.dataset.paint;mode==='review'?renderReview():renderManual();});$$('[data-sticker]').forEach(b=>b.onclick=()=>{if(busy)return;const [f,i]=b.dataset.sticker.split(':');faces[f][+i]=paint;delete samples[f];uncertain[f]=(uncertain[f]||[]).filter(v=>v!==+i);states=[];moves=[];moveIndex=0;if(!faces[f].includes('?'))done.add(f);view?.setState(faces);const step=document.querySelector('[data-step=solve]');if(step)step.disabled=true;mode==='review'?renderReview():renderManual();});}
function renderManual(){ $('#scan-area').innerHTML=`<div class="manual-input">${faceGrid(face,true)}<p>Choose a color, then tap a sticker to paint it.</p>${palette()}<button id="save-manual" class="primary" ${faces[face].includes('?')?'disabled':''}>Save ${INFO[face].name.toLowerCase()} face ${icon('check',16)}</button></div>`;bindPaint();$('#save-manual').onclick=()=>{done.add(face);delete samples[face];demo=false;view?.setState(faces);if(done.size===6)setMode('review');else{face=SCAN_ORDER.find(f=>!done.has(f));renderScan();}};}
function renderReview(){const validation=validate(toString(faces),Cube),counts=Object.fromEntries(ORDER.map(c=>[c,toString(faces).split(c).length-1]));$('#panel-content').innerHTML=`<div class="panel-heading"><div><div class="eyebrow">A QUICK DOUBLE-CHECK</div><h2>Do these colors match?</h2></div><span class="counter">6<small> sides</small></span></div><p class="panel-description">Compare each face with your cube. Select a color below to fix any sticker.</p><div class="review-grid">${SCAN_ORDER.map(f=>`<div class="review-face"><div class="review-face-label"><b>${INFO[f].name}</b><span>${INFO[f].color}</span></div>${faceGrid(f)}<div class="review-face-actions"><button data-rotate="${f}" aria-label="Rotate ${INFO[f].name} face clockwise" ${busy?'disabled':''}>${icon('rotate',13)} Rotate</button><button data-rescan="${f}" ${busy?'disabled':''}>Retake</button></div></div>`).join('')}</div>${palette()}<div class="color-counts">${ORDER.map(f=>`<span class="${counts[f]!==9?'count-wrong':''}"><i style="background:${INFO[f].hex}"></i>${counts[f]}<small>/9</small></span>`).join('')}</div>${Object.values(uncertain).some(a=>a.length)?'<p class="uncertain-note">Stickers with a dotted outline need a closer look.</p>':''}<div class="validation ${validation.ok?'valid':'invalid'}" role="status">${icon(validation.ok?'check':'eye',18)}<span>${validation.ok?(validation.solved?'Your cube is already solved. Nicely done!':'All pieces check out. Your cube is ready to solve.') : validation.message}</span></div><div class="review-bottom"><button id="back-scan" class="text-button" ${busy?'disabled':''}>Back to scanning</button><button id="solve" class="primary" ${!validation.ok||busy?'disabled':''}>${busy?'<span class="spinner"></span>':icon('play',16)} ${busy?'Finding your solution…':validation.solved?'See solved cube':'Show my solution'}</button></div><div id="solver-status" role="status" class="solver-status"></div>`;bindPaint();$$('[data-rotate]').forEach(b=>b.onclick=()=>{const f=b.dataset.rotate;faces[f]=rotateFace(faces[f]);delete samples[f];uncertain[f]=[];states=[];moves=[];moveIndex=0;view?.setState(faces);renderReview();});$$('[data-rescan]').forEach(b=>b.onclick=()=>{const f=b.dataset.rescan;if(!cubeIsFinished()){done.delete(f);delete samples[f];}scanCube(f);});$('#back-scan').onclick=()=>scanCube();$('#solve').onclick=solve;}
async function solve(){const state=toString(faces),valid=validate(state,Cube);if(!valid.ok)throw new Error(valid.message);stopCamera();busy=true;renderReview();const id=++solveGeneration;worker?.terminate();worker=new Worker('solver-worker.js');let timeout=setTimeout(()=>{if(id!==solveGeneration)return;worker.terminate();busy=false;renderReview();$('#solver-status').textContent='This solve took too long. Try again, or check the cube colors.';},60000);worker.onmessage=({data})=>{if(id!==solveGeneration)return;if(data.type==='progress'){if($('#solver-status'))$('#solver-status').textContent=data.message;return;}clearTimeout(timeout);busy=false;if(data.type==='error'){if(mode==='review'){renderReview();$('#solver-status').textContent=data.message;}return;}moves=data.algorithm.trim()?data.algorithm.trim().split(/\s+/):[];let c=Cube.fromString(state);states=[state];moves.forEach(m=>{c.move(m);states.push(c.asString());});if(!c.isSolved()){notify('The solution did not verify. Please try again.');return;}moveIndex=0;mode='solve';render();};worker.onerror=()=>{clearTimeout(timeout);busy=false;if(mode==='review'){renderReview();$('#solver-status').textContent='The solver could not load. Refresh the page and try again.';}};worker.postMessage({state,id});}
function renderSolve(){const complete=moveIndex===moves.length,move=moves[moveIndex];$('#panel-content').innerHTML=`<div class="panel-heading"><div><div class="eyebrow">${demo?'PRACTICE SOLVE':'YOUR GUIDED SOLVE'}</div><h2>${complete?'That’s a solved cube.':'One move. Then the next.'}</h2></div><span class="counter">${moveIndex}<small>/ ${moves.length} moves</small></span></div><div class="solve-progress"><div style="width:${moves.length?moveIndex/moves.length*100:100}%"></div></div>${complete?`<div class="solved-state"><div class="success-icon">${icon('check',42)}</div><h3>You made every turn count.</h3><p>${demo?'That was a practice cube. Ready to try your own?':'Compare your cube to the preview. All six faces should now be a single color.'}</p><button id="new-cube" class="primary">Scan my cube ${icon('camera',17)}</button></div>`:`<div class="move-card"><span class="eyebrow">NEXT · MOVE ${moveIndex+1}</span><div class="move-symbol"><strong>${move.replace("'",'′')}</strong><span>${move.endsWith('2')?'180°':move.endsWith("'")?'↶':'↷'}</span></div><h3>${INFO[move[0]].name} face ${move.endsWith('2')?'· half-turn':move.endsWith("'")?'· counterclockwise':'· clockwise'}</h3><p>${explain(move)}</p><button id="focus-face" class="text-button">${icon('eye',16)} Look straight at this face</button></div>`}<div class="play-controls"><button id="prev-move" class="secondary" ${moveIndex===0||animating?'disabled':''}>Previous</button><button id="auto-play" class="play-button" aria-label="${playing?'Pause':'Play'} automatic moves" ${complete?'disabled':''}>${icon(playing?'pause':'play',20)}</button><button id="next-move" class="primary" ${complete||animating?'disabled':''}>${animating?'Turning…':'Next move'}</button></div><div class="player-settings"><label>Speed <select id="play-speed"><option value="2200">Slow & steady</option><option value="1200">Comfortable</option><option value="500">Quick practice</option></select></label><button id="restart-solve" class="text-button">${icon('rotate',14)} Start over</button></div><div class="move-sequence" aria-label="Solution moves">${moves.map((m,i)=>`<button data-jump="${i}" class="${i<moveIndex?'past':i===moveIndex?'current':''}" aria-label="View cube before move ${i+1}: ${m}">${m.replace("'",'′')}</button>`).join('')}</div><div class="solve-note">${icon('book',20)}<p>Clockwise is always viewed from the face you’re turning. B and D can feel backwards—use “Look straight at this face” to check.</p></div><button id="edit-cube" class="text-button edit-cube">My cube looks different · Check starting colors</button>`;
 $('#play-speed').value=String(playDelay);$('#play-speed').onchange=e=>playDelay=+e.target.value;
 $('#prev-move').onclick=()=>jump(moveIndex-1);$('#next-move').onclick=()=>nextMove();$('#auto-play').onclick=()=>{playing=!playing;playGeneration++;if(playing)autoPlay(playGeneration);else renderSolve();};$('#restart-solve').onclick=()=>jump(0);$$('[data-jump]').forEach(b=>b.onclick=()=>jump(+b.dataset.jump));$('#focus-face')?.addEventListener('click',()=>view?.focus(move[0]));$('#new-cube')?.addEventListener('click',()=>newCube());$('#edit-cube').onclick=()=>setMode('review');
}
let playDelay=2200,playGeneration=0;
async function nextMove(auto=false){if(animating||moveIndex>=moves.length)return;if(!auto){playing=false;playGeneration++;}animating=true;renderSolve();const current=moveIndex;try{if(view)await view.turn(moves[current],fromString(states[current+1]),Math.min(1000,playDelay*.55));moveIndex=current+1;}finally{animating=false;if(mode==='solve')renderSolve();}}
async function autoPlay(token){while(playing&&token===playGeneration&&mode==='solve'&&moveIndex<moves.length){await nextMove(true);await new Promise(r=>setTimeout(r,playDelay));}if(token!==playGeneration)return;if(moveIndex===moves.length)playing=false;if(mode==='solve')renderSolve();}
function jump(i){if(animating)return;playing=false;playGeneration++;moveIndex=Math.max(0,Math.min(moves.length,i));view?.setState(fromString(states[moveIndex]));renderSolve();}
// Forget the active cube: colors, captured faces, camera samples, flags, solution, demo flag and selected face.
function clearCube(){stopCamera();worker?.terminate();solveGeneration++;busy=false;playing=false;playGeneration++;faces=blankFaces();done=new Set();samples={};uncertain={};states=[];moves=[];moveIndex=0;demo=false;face='F';scanError='';}
function loadDemo(){if(animating)return;clearCube();faces=fromString(new Cube().move("R U R' F2 D L2 B U2 R2 F D' L B2 R U' F2").asString());done=new Set(ORDER);demo=true;mode='review';render();notify('Demo loaded. Check the colors, then try the guided solve.');}
function newCube(first='F'){if(animating)return;clearCube();face=first;mode='scan';render();}
// The demo and a finished solve no longer describe the cube in the user's hands, so scanning them starts a new cube.
function cubeIsFinished(){return demo||states.length>0&&moveIndex===moves.length;}
function scanCube(next){if(animating)return;if(cubeIsFinished()){const wasDemo=demo;newCube(next);notify(wasDemo?'Demo cleared. Let’s scan your cube.':'New cube started. Your last cube was cleared.');return;}face=next??face;setMode('scan');}
function renderLearn(){const l=lessons[lesson];$('#panel-content').innerHTML=`<div class="eyebrow">THE BEGINNER’S CORNER</div><h2>Small lessons. Big difference.</h2><div class="lesson-tabs">${lessons.map((l,i)=>`<button data-lesson="${i}" class="${i===lesson?'active':''}" aria-label="Lesson ${i+1}">${i+1}</button>`).join('')}</div><article class="lesson"><div class="eyebrow">${l.label}</div><h3>${l.title}</h3><p>${l.body}</p><div class="lesson-tip">${icon('spark',22)}<p>${l.tip}</p></div></article>${lesson===2?'<div class="notation-table"><span><b>R</b> 90° clockwise</span><span><b>R′</b> 90° counterclockwise</span><span><b>R2</b> 180° half-turn</span></div>':''}<div class="lesson-actions"><button id="prev-lesson" class="secondary" ${lesson===0?'disabled':''}>Previous</button><button id="next-lesson" class="primary">${lesson===3?'Try my cube':'Next lesson'}</button></div>`;$$('[data-lesson]').forEach(b=>b.onclick=()=>{lesson=+b.dataset.lesson;renderLearn();});$('#prev-lesson').onclick=()=>{lesson--;renderLearn();};$('#next-lesson').onclick=()=>{if(lesson===3){if(cubeIsFinished()||done.size<6)scanCube();else setMode('review');return;}lesson++;renderLearn();};view?.setState(fromString(SOLVED));l.face?view?.focus(l.face):view?.reset();$('#stage-tip-text').textContent='Explore the solved cube. Notice that the centers tell you which face is which.';$('#cube-badge').textContent='LEARNING VIEW';}
window.addEventListener('pagehide',()=>{stopCamera();playing=false;worker?.terminate();});document.addEventListener('visibilitychange',()=>{if(document.hidden){playing=false;if(scanner?.active){stopCamera();if(mode==='scan'){scanError='Camera paused while the app was in the background. Start it again when you’re ready.';renderScan();}}}});
render();
// Feature-detected WebMCP uses the same state and validated actions as the visible app.
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_cube_state',description:'Read scanned colors, validation, current view, and guided-solve progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({facelets:toString(faces),capturedFaces:[...done],validation:validate(toString(faces),Cube),view:mode,displayedFacelets:mode==='solve'&&states.length?states[moveIndex]:toString(faces),moveIndex,moveCount:moves.length})});register({name:'set_cube_colors',description:'Replace all six faces with a validated 54-character URFDLB facelet string and open color review. Does not solve or start the camera.',inputSchema:{type:'object',properties:{facelets:{type:'string',minLength:54,maxLength:54}},required:['facelets'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(animating||busy)throw new Error('Wait for the current operation to finish.');if(!input||typeof input.facelets!=='string')throw new Error('facelets is required');const v=validate(input.facelets,Cube);if(!v.ok)throw new Error(v.message);clearCube();faces=fromString(input.facelets);done=new Set(ORDER);mode='review';render();return {status:'ready_for_review',validation:v};}});register({name:'show_solution_position',description:'Show the cube after a chosen number of moves in the existing verified solution. Does not turn the physical cube.',inputSchema:{type:'object',properties:{completedMoves:{type:'integer',minimum:0}},required:['completedMoves'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(animating||busy||!states.length)throw new Error('A ready solution is required.');const n=input?.completedMoves;if(!Number.isInteger(n)||n<0||n>moves.length)throw new Error('Move position is out of range.');setMode('solve');jump(n);return {completedMoves:moveIndex,totalMoves:moves.length};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
